-- 17A P4 item (4): profile_content 'read all' -> public (archived IS NOT TRUE) + owners (own rows incl. archived) + admins (all). Table ACL untouched (order-independent of 10A APPLY-1C). [APPLY]
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Run it a second time and it refuses at the guard (state is no longer the captured one) with nothing changed.
-- No object, no row and no data is deleted by this pack.
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A / 13A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- 1. DRIFT GUARD: live state must be EXACTLY the captured prod state (policies by name/shape/predicate, bucket settings, ACL classes, prerequisite functions). Anything else aborts with nothing applied.
DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'public.profile_content'::regclass), 'ABSENT');
  IF v IS DISTINCT FROM 'true/false' THEN f := f || ('req.rls_on_not_forced: expected true/false but live is ' || v); END IF;
  v := coalesce((SELECT CASE WHEN coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') = '{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}' THEN 'A0_before_1C' WHEN coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') = '{anon=r/postgres,authenticated=arwd/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}' THEN 'A1_after_1C' ELSE 'OTHER:' || coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') END FROM pg_class c WHERE c.oid = 'public.profile_content'::regclass), 'ABSENT');
  IF v <> ALL (ARRAY['A0_before_1C','A1_after_1C']) THEN f := f || ('req.acl_class_A0_or_A1: expected A0_before_1C OR A1_after_1C but live is ' || v); END IF;
  v := coalesce((SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.profile_content'::regclass AND a.attname = 'archived' AND NOT a.attisdropped), 'ABSENT');
  IF v IS DISTINCT FROM 'boolean' THEN f := f || ('req.archived_column: expected boolean but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM unnest(ARRAY['id','profile_slug','kind','data','created_by','created_at','archived']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_content') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT');
  IF v IS DISTINCT FROM '7' THEN f := f || ('req.columns: expected 7 but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM unnest(ARRAY['profile_slug','owner_id']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_owners') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT');
  IF v IS DISTINCT FROM '2' THEN f := f || ('req.profile_owners_cols: expected 2 but live is ' || v); END IF;
  v := coalesce((to_regprocedure('public.is_admin()') IS NOT NULL)::text, 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.is_admin_exists: expected true but live is ' || v); END IF;
  v := coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.is_admin()'), 'EXECUTE')::text), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.is_admin_exec_authenticated: expected true but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.cmd IN ('INSERT','UPDATE','DELETE')), 'ABSENT');
  IF v IS DISTINCT FROM '3' THEN f := f || ('req.write_policies_present: expected 3 but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.cmd = 'ALL'), 'ABSENT');
  IF v IS DISTINCT FROM '0' THEN f := f || ('req.no_all_cmd_policy: expected 0 but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.cmd = 'SELECT'), 'ABSENT');
  IF v IS DISTINCT FROM 'profile_content read all' THEN f := f || ('pc.read_policies: expected profile_content read all but live is ' || v); END IF;
  v := coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive || '|' || coalesce(p.qual,'(null)') FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.policyname = 'profile_content read all'), 'ABSENT');
  IF v IS DISTINCT FROM 'SELECT|public|PERMISSIVE|true' THEN f := f || ('pc.read_all.shape: expected SELECT|public|PERMISSIVE|true but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '17A APPLY-P4: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

-- 2. INVARIANT SNAPSHOT: everything this pack must NOT change (ACL fingerprints sorted, RLS flags, every other policy, every untouched bucket row, the object name set).
CREATE TEMP TABLE _kil17a_inv ON COMMIT DROP AS
SELECT 'inv.pc_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'public.profile_content'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.pc_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'public.profile_content'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.pc_write_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.cmd <> 'SELECT'), '(null)')::text AS val
UNION ALL SELECT 'inv.pc_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(c.id::text || coalesce(c.archived::text,'n'), '|' ORDER BY c.id)),'-') FROM public.profile_content c), '(null)')::text AS val
UNION ALL SELECT 'inv.pc_columns_md5'::text AS name, coalesce((SELECT md5(string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod), ',' ORDER BY a.attnum)) FROM pg_attribute a WHERE a.attrelid = 'public.profile_content'::regclass AND a.attnum > 0 AND NOT a.attisdropped), '(null)')::text AS val;

-- 3. THE FIX
-- profile_content: "profile_content read all" (USING true) lets anon read ARCHIVED rows (autopilot review-queue items, owner-archived posts). Replace with three scoped policies.
-- Public: archived IS NOT TRUE (not "= false": a NULL archived row stays public exactly as today). Owners: their own rows incl. archived (the profile page Archive list and Unarchive flow need it). Admins: everything (review queue).
DROP POLICY "profile_content read all" ON public.profile_content;
CREATE POLICY "profile_content read public" ON public.profile_content AS PERMISSIVE FOR SELECT TO public USING (archived IS NOT TRUE);
CREATE POLICY "profile_content read owner" ON public.profile_content AS PERMISSIVE FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM public.profile_owners po WHERE po.profile_slug = profile_content.profile_slug AND po.owner_id = (SELECT auth.uid())));
CREATE POLICY "profile_content read admin" ON public.profile_content AS PERMISSIVE FOR SELECT TO authenticated USING (public.is_admin());

-- 4. POST-CHECKS (assert; a failure rolls the whole transaction back)
DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'req.rls_on_not_forced' AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'public.profile_content'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'req.acl_class_A0_or_A1' AS name, coalesce((SELECT CASE WHEN coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') = '{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}' THEN 'A0_before_1C' WHEN coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') = '{anon=r/postgres,authenticated=arwd/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}' THEN 'A1_after_1C' ELSE 'OTHER:' || coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') END FROM pg_class c WHERE c.oid = 'public.profile_content'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'req.archived_column' AS name, coalesce((SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.profile_content'::regclass AND a.attname = 'archived' AND NOT a.attisdropped), 'ABSENT') AS actual
  UNION ALL SELECT 'req.columns' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['id','profile_slug','kind','data','created_by','created_at','archived']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_content') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.profile_owners_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['profile_slug','owner_id']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_owners') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.is_admin_exists' AS name, coalesce((to_regprocedure('public.is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.is_admin_exec_authenticated' AS name, coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.is_admin()'), 'EXECUTE')::text), 'ABSENT') AS actual
  UNION ALL SELECT 'req.write_policies_present' AS name, coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.cmd IN ('INSERT','UPDATE','DELETE')), 'ABSENT') AS actual
  UNION ALL SELECT 'req.no_all_cmd_policy' AS name, coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.cmd = 'ALL'), 'ABSENT') AS actual
  UNION ALL SELECT 'rec.null_archived_rows' AS name, coalesce((SELECT count(*)::text FROM public.profile_content WHERE archived IS NULL), 'ABSENT') AS actual
  UNION ALL SELECT 'rec.archived_true_rows' AS name, coalesce((SELECT count(*)::text FROM public.profile_content WHERE archived), 'ABSENT') AS actual
  UNION ALL SELECT 'rec.acl_sorted' AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'public.profile_content'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'pc.read_policies' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.cmd = 'SELECT'), 'ABSENT') AS actual
  UNION ALL SELECT 'pc.read_public.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive || '|' || (p.qual ~ 'archived IS NOT TRUE')::text FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.policyname = 'profile_content read public'), 'ABSENT') AS actual
  UNION ALL SELECT 'pc.read_owner.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive || '|' || (p.qual ~ 'profile_owners' AND p.qual ~ 'auth.uid')::text FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.policyname = 'profile_content read owner'), 'ABSENT') AS actual
  UNION ALL SELECT 'pc.read_admin.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive || '|' || (p.qual ~ 'is_admin')::text FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'profile_content' AND p.policyname = 'profile_content read admin'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.rls_on_not_forced', 'true/false', ARRAY['true/false']::text[]),
  ('req.acl_class_A0_or_A1', 'A0_before_1C OR A1_after_1C', ARRAY['A0_before_1C','A1_after_1C']::text[]),
  ('req.archived_column', 'boolean', ARRAY['boolean']::text[]),
  ('req.columns', '7', ARRAY['7']::text[]),
  ('req.profile_owners_cols', '2', ARRAY['2']::text[]),
  ('req.is_admin_exists', 'true', ARRAY['true']::text[]),
  ('req.is_admin_exec_authenticated', 'true', ARRAY['true']::text[]),
  ('req.write_policies_present', '3', ARRAY['3']::text[]),
  ('req.no_all_cmd_policy', '0', ARRAY['0']::text[]),
