SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P4: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
