  ('req.archived_column', 'boolean', ARRAY['boolean']::text[]),
  ('req.columns', '7', ARRAY['7']::text[]),
  ('req.profile_owners_cols', '2', ARRAY['2']::text[]),
  ('req.is_admin_exists', 'true', ARRAY['true']::text[]),
  ('req.is_admin_exec_authenticated', 'true', ARRAY['true']::text[]),
  ('req.write_policies_present', '3', ARRAY['3']::text[]),
  ('req.no_all_cmd_policy', '0', ARRAY['0']::text[]),
  ('rec.null_archived_rows', NULL, NULL),
  ('rec.archived_true_rows', NULL, NULL),
  ('rec.acl_sorted', NULL, NULL),
  ('pc.read_policies', 'profile_content read admin,profile_content read owner,profile_content read public', ARRAY['profile_content read admin,profile_content read owner,profile_content read public']::text[]),
  ('pc.read_public.shape', 'SELECT|public|PERMISSIVE|true', ARRAY['SELECT|public|PERMISSIVE|true']::text[]),
  ('pc.read_owner.shape', 'SELECT|authenticated|PERMISSIVE|true', ARRAY['SELECT|authenticated|PERMISSIVE|true']::text[]),
  ('pc.read_admin.shape', 'SELECT|authenticated|PERMISSIVE|true', ARRAY['SELECT|authenticated|PERMISSIVE|true']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'POST' AS expected, 'POST' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
COMMIT;
